#!/usr/bin/env node
// The proof for mv make's Node-only gates (board, cards check, lint, generated files, the approve rule): each is broken on purpose on a scratch copy
// of a real video and seen to stop the pipeline with the file and field to fix. No Unity, no Gen, nothing written to the real video.
//   node Director/tools/mv/make-test.mjs [<video>]     default hawkespunch; the copy is videos/_make_tmp, removed after
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { PROJECT, DIRECTOR } from './score.mjs';

const SRC = path.join(DIRECTOR, 'videos', process.argv[2] ?? 'hawkespunch'), TMP = path.join(DIRECTOR, 'videos', '_make_tmp');
const results = [];
const ok = (name, c, detail = '') => { results.push(!!c); console.log(`${c ? 'ok  ' : 'FAIL'} ${name}${detail && !c ? `\n     ${detail.slice(0, 600).replace(/\n/g, '\n     ')}` : ''}`); };
const mv = (...a) => { const r = spawnSync(process.execPath, [path.join(DIRECTOR, 'mv.mjs'), ...a], { cwd: PROJECT, encoding: 'utf8' }); return { status: r.status, out: (r.stdout ?? '') + (r.stderr ?? '') }; };
const make = (...a) => mv('make', '_make_tmp', ...a);
const edit = (rel, fn) => { const f = path.join(TMP, rel); fs.writeFileSync(f, fn(fs.readFileSync(f, 'utf8'))); };

function fresh() {
  fs.rmSync(TMP, { recursive: true, force: true });
  fs.mkdirSync(TMP, { recursive: true });
  for (const n of ['cut.json', 'score.json', 'style.json', 'song.json', 'lines.json', 'duck.json', 'silence.json', 'cards.map.json', 'generated.json', 'cards', 'sequences', 'acts', 'storyboard', 'tweaks', 'notes'])
    if (fs.existsSync(path.join(SRC, n))) fs.cpSync(path.join(SRC, n), path.join(TMP, n), { recursive: true, filter: (f) => !/[\\/]storyboard[\\/].*\.(png|jpg|jpeg)$/i.test(f) });
  // The manifest's tool commands name the video ("mv --video hawkespunch cards compile"): point them at the copy, so nothing run here can regenerate the real one.
  const man = path.join(TMP, 'generated.json'), name = path.basename(SRC);
  if (fs.existsSync(man)) { const m = JSON.parse(fs.readFileSync(man, 'utf8')); for (const e of Object.values(m.files ?? {})) if (e.tool) e.tool = e.tool.split(` ${name}`).join(' _make_tmp'); fs.writeFileSync(man, JSON.stringify(m, null, 1)); }
}

try {
  fresh();
  let r = make('cards');
  ok('the copy passes board and cards as the real video does', r.status === 0 && /\[2\/8\] cards\s+PASS/.test(r.out), r.out);

  // board: a field missing on one shot names the shot and the field
  edit('storyboard/shots.json', (t) => { const j = JSON.parse(t); j.shots[3].lens = 0; delete j.shots[5].change; return JSON.stringify(j, null, 1); });
  r = make('board');
  ok('board: lens 0 and a missing "change" stop it, each with its shots[i] field', r.status === 2 && /field:\s+shots\[3\][^\n]*\.lens/.test(r.out) && /field:\s+shots\[5\][^\n]*\.change/.test(r.out), r.out);
  fresh();
  // board: the craft rules (a 7-shot burst)
  edit('storyboard/shots.json', (t) => { const j = JSON.parse(t); for (let i = 10; i < 17; i++) j.shots[i].frames = 12; return JSON.stringify(j, null, 1); });
  r = make('board');
  ok('board: a burst of 7 short shots is refused with the rule', r.status === 2 && /burst of 7 shots/.test(r.out), r.out);
  fresh();
  // board -> cards: a board shot with no card
  edit('storyboard/shots.json', (t) => { const j = JSON.parse(t); j.shots.splice(20, 0, { ...j.shots[20], id: 'zz_new' }); return JSON.stringify(j, null, 1); });
  r = make('board');
  ok('board: a board shot with no card in cut.json is named, with board2cards as the fix', r.status === 2 && /zz_new/.test(r.out) && /board2cards/.test(r.out), r.out);
  fresh();

  // cards: a hand edit on a generated act
  edit('acts/70-lines.json', (t) => t + '// a hand note\n'); // valid JSONC, so only the manifest can catch it
  r = make('cards');
  ok('cards: a hand edit on acts/70-lines.json is EDITED BY HAND with the tool to run', r.status === 2 && /70-lines\.json is generated and was EDITED BY HAND/.test(r.out) && /punch_lines\.mjs/.test(r.out), r.out);
  fresh();
  // cards: an act that says GENERATED with no tool registered
  fs.writeFileSync(path.join(TMP, 'acts', '99-orphan.json'), '// GENERATED by a tool nobody registered\n{ "cues": [] }\n');
  r = make('cards');
  ok('cards: an unregistered generated act stops it with mv generated adopt', r.status === 2 && /99-orphan\.json says GENERATED/.test(r.out) && /mv generated adopt/.test(r.out), r.out);
  fresh();
  // cards: lint, a key that has no effect (speed on a native anim: use rate)
  edit('cards/board.yaml', (t) => t.replace(/(do: anim, on: person, clip: [\w]+)/, '$1, speed: 0.5'));
  r = make('cards');
  ok('cards: `speed` on a native anim is a lint error with the fix (rate)', r.status === 2 && /speed/.test(r.out) && /rate/.test(r.out), r.out);
  fresh();

  // the human gate: approve needs J's words, a test, and a hero shot
  r = mv('approve', '_make_tmp', 'p02');
  ok('approve: refused without --note (J\'s own words)', r.status !== 0 && /J's own words/.test(r.out), r.out);
  r = mv('approve', '_make_tmp', 'p02', '--note', 'yes');
  ok('approve: refused when no test was rendered', r.status !== 0 && /no test of p02/.test(r.out), r.out);
  r = make('status');
  ok('make status prints the stage table', r.status === 0 && /1\s+board/.test(r.out) && /8\s+final/.test(r.out), r.out);
  r = make('nonsense');
  ok('make with an unknown stage names the stages', r.status !== 0 && /board, cards, build/.test(r.out), r.out);
} finally {
  fs.rmSync(TMP, { recursive: true, force: true });
}
const bad = results.filter((x) => !x).length;
console.log(`\nmake-test: ${results.length - bad} of ${results.length} passed${bad ? `, ${bad} FAILED` : ''}`);
process.exitCode = bad ? 1 : 0;
